class AdmissionStatusKind(enum.Enum):
    
    ADMISSION_NOT_SENT = 0
    
    ADMISSION_PENDING = 1
    
    ADMISSION_WAITING = 2
    
    ADMISSION_QUEUED = 3
    
    APPROVAL_PENDING = 4
    
    APPROVAL_REQUESTED = 5
    
    ADMISSION_UNAVAILABLE = 6
    
    ADMISSION_RECOVERY_REQUIRED = 7
    
    ADMISSION_REPLIED = 8
    


class _UniffiFfiConverterTypeAdmissionStatusKind(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return AdmissionStatusKind.ADMISSION_NOT_SENT
        if variant == 2:
            return AdmissionStatusKind.ADMISSION_PENDING
        if variant == 3:
            return AdmissionStatusKind.ADMISSION_WAITING
        if variant == 4:
            return AdmissionStatusKind.ADMISSION_QUEUED
        if variant == 5:
            return AdmissionStatusKind.APPROVAL_PENDING
        if variant == 6:
            return AdmissionStatusKind.APPROVAL_REQUESTED
        if variant == 7:
            return AdmissionStatusKind.ADMISSION_UNAVAILABLE
        if variant == 8:
            return AdmissionStatusKind.ADMISSION_RECOVERY_REQUIRED
        if variant == 9:
            return AdmissionStatusKind.ADMISSION_REPLIED
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == AdmissionStatusKind.ADMISSION_NOT_SENT:
            return
        if value == AdmissionStatusKind.ADMISSION_PENDING:
            return
        if value == AdmissionStatusKind.ADMISSION_WAITING:
            return
        if value == AdmissionStatusKind.ADMISSION_QUEUED:
            return
        if value == AdmissionStatusKind.APPROVAL_PENDING:
            return
        if value == AdmissionStatusKind.APPROVAL_REQUESTED:
            return
        if value == AdmissionStatusKind.ADMISSION_UNAVAILABLE:
            return
        if value == AdmissionStatusKind.ADMISSION_RECOVERY_REQUIRED:
            return
        if value == AdmissionStatusKind.ADMISSION_REPLIED:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == AdmissionStatusKind.ADMISSION_NOT_SENT:
            buf.write_i32(1)
        if value == AdmissionStatusKind.ADMISSION_PENDING:
            buf.write_i32(2)
        if value == AdmissionStatusKind.ADMISSION_WAITING:
            buf.write_i32(3)
        if value == AdmissionStatusKind.ADMISSION_QUEUED:
            buf.write_i32(4)
        if value == AdmissionStatusKind.APPROVAL_PENDING:
            buf.write_i32(5)
        if value == AdmissionStatusKind.APPROVAL_REQUESTED:
            buf.write_i32(6)
        if value == AdmissionStatusKind.ADMISSION_UNAVAILABLE:
            buf.write_i32(7)
        if value == AdmissionStatusKind.ADMISSION_RECOVERY_REQUIRED:
            buf.write_i32(8)
        if value == AdmissionStatusKind.ADMISSION_REPLIED:
            buf.write_i32(9)



