class RelayTrust:
    """
    TLS trust for operator relays.
"""
    def __init__(self):
        raise RuntimeError("RelayTrust cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    @dataclass
    class WEB_PKI:
        """
        The built-in WebPKI roots.
"""
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "RelayTrust.WEB_PKI()".format()
        def __eq__(self, other):
            if not isinstance(other, RelayTrust):
                return NotImplemented
            if not other.is_WEB_PKI():
                return False
            return True

    @dataclass
    class CUSTOM_ROOTS:
        """
        Only these DER-encoded root certificates, for a private CA.
"""
        
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

    
            
            

    
        def __str__(self):
            return f"RelayTrust.CUSTOM_ROOTS{self._values!r}"
        def __eq__(self, other):
            if not isinstance(other, RelayTrust):
                return NotImplemented
            if not other.is_CUSTOM_ROOTS():
                return False
            return self._values == other._values

    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_WEB_PKI(self) -> bool:
        return isinstance(self, RelayTrust.WEB_PKI)
    def is_web_pki(self) -> bool:
        return isinstance(self, RelayTrust.WEB_PKI)
    def is_CUSTOM_ROOTS(self) -> bool:
        return isinstance(self, RelayTrust.CUSTOM_ROOTS)
    def is_custom_roots(self) -> bool:
        return isinstance(self, RelayTrust.CUSTOM_ROOTS)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
RelayTrust.WEB_PKI = type("RelayTrust.WEB_PKI", (RelayTrust.WEB_PKI, RelayTrust,), {})  # type: ignore
RelayTrust.CUSTOM_ROOTS = type("RelayTrust.CUSTOM_ROOTS", (RelayTrust.CUSTOM_ROOTS, RelayTrust,), {})  # type: ignore




class _UniffiFfiConverterTypeRelayTrust(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return RelayTrust.WEB_PKI(
            )
        if variant == 2:
            return RelayTrust.CUSTOM_ROOTS(
                _UniffiFfiConverterSequenceBytes.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_WEB_PKI():
            return
        if value.is_CUSTOM_ROOTS():
            _UniffiFfiConverterSequenceBytes.check_lower(value._values[0])
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_WEB_PKI():
            buf.write_i32(1)
        if value.is_CUSTOM_ROOTS():
            buf.write_i32(2)
            _UniffiFfiConverterSequenceBytes.write(value._values[0], buf)



