class _UniffiFfiConverterSequenceTypeEndpointId(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        for item in value:
            arachne_api._UniffiFfiConverterTypeEndpointId.check_lower(item)

    @classmethod
    def write(cls, value, buf):
        items = len(value)
        buf.write_i32(items)
        for item in value:
            arachne_api._UniffiFfiConverterTypeEndpointId.write(item, buf)

    @classmethod
    def read(cls, buf):
        count = buf.read_i32()
        if count < 0:
            raise InternalError("Unexpected negative sequence length")

        return [
            arachne_api._UniffiFfiConverterTypeEndpointId.read(buf) for i in range(count)
        ]

