class NearbyMode(enum.Enum):
    """
    How a nearby workspace admits people.
"""
    
    REQUEST_ACCESS = 0
    """
    A person asks; an administrator approves.
"""
    
    OPEN_JOINING = 1
    """
    Anyone nearby with the link may join.
"""
    


class _UniffiFfiConverterTypeNearbyMode(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return NearbyMode.REQUEST_ACCESS
        if variant == 2:
            return NearbyMode.OPEN_JOINING
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == NearbyMode.REQUEST_ACCESS:
            return
        if value == NearbyMode.OPEN_JOINING:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == NearbyMode.REQUEST_ACCESS:
            buf.write_i32(1)
        if value == NearbyMode.OPEN_JOINING:
            buf.write_i32(2)



