class _UniffiFfiConverterTypeContext:
    @staticmethod
    def lift(value: int) -> Context:
        return Context._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: Context):
        if not isinstance(value, Context):
            raise TypeError("Expected Context instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: Context) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> Context:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: Context, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))

